#root {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem;
  text-align: center;
}

.logo {
  height: 6em;
  padding: 1.5em;
  will-change: filter;
  transition: filter 300ms;
}
.logo:hover {
  filter: drop-shadow(0 0 2em #646cffaa);
}
.logo.react:hover {
  filter: drop-shadow(0 0 2em #61dafbaa);
}

@keyframes logo-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: no-preference) {
  a:nth-of-type(2) .logo {
    animation: logo-spin infinite 20s linear;
  }
}

.card {
  padding: 2em;
}

.read-the-docs {
  color: #888;
}

import { useState } from 'react';
import { useDashboard } from './hooks/useDashboard';
import Header   from './components/Header';
import Nav      from './components/Nav';
import Overview  from './components/tabs/Overview';
import Agents    from './components/tabs/Agents';
import Tasks     from './components/tabs/Tasks';
import Projects  from './components/tabs/Projects';
import Velocity  from './components/tabs/Velocity';
import Budget    from './components/tabs/Budget';
import OKRs      from './components/tabs/OKRs';
import RD        from './components/tabs/RD';
import Broadcast from './components/tabs/Broadcast';
import Crons     from './components/tabs/Crons';
import HITLTab   from './components/tabs/HITL';
import Knowledge from './components/tabs/Knowledge';
import Comms     from './components/tabs/Comms';
import AlertsTab from './components/tabs/Alerts';

const TABS = [
  'Overview','Agents','Tasks','Projects',
  'Crons','HITL','Alerts',
  'Velocity','Budget','OKRs',
  'Knowledge','Comms',
  'R&D','Broadcast',
];

function Connecting() {
  return (
    <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center',
      height:'calc(100vh - 100px)', gap:16 }}>
      <span style={{ fontSize:32 }}>🦅</span>
      <div style={{ color:'var(--cyan)', fontSize:14, fontWeight:600 }}>Connecting to Ops Room…</div>
      <div style={{ color:'var(--muted)', fontSize:11 }}>Waiting for SSE push from dashboard.py</div>
    </div>
  );
}

export default function App() {
  const [activeTab, setActiveTab] = useState('Overview');
  const { data, connected, lastUpdated, updateCount } = useDashboard();

  const tabProps = { data, lastUpdated };

  // Badge counts for nav tabs
  const badges = data ? {
    'HITL':   (data.hitl_tasks  || []).length,
    'Alerts': (data.alerts      || []).length,
    'Crons':  (data.crons || []).filter(j => (j._consecutive_errors || 0) >= 3).length,
  } : {};

  const renderTab = () => {
    if (!data) return <Connecting />;
    switch (activeTab) {
      case 'Overview':  return <Overview  {...tabProps} />;
      case 'Agents':    return <Agents    {...tabProps} />;
      case 'Tasks':     return <Tasks     {...tabProps} />;
      case 'Projects':  return <Projects  {...tabProps} />;
      case 'Velocity':  return <Velocity  {...tabProps} />;
      case 'Budget':    return <Budget    {...tabProps} />;
      case 'OKRs':      return <OKRs      {...tabProps} />;
      case 'R&D':       return <RD        {...tabProps} />;
      case 'Broadcast': return <Broadcast {...tabProps} />;
      case 'Crons':     return <Crons     {...tabProps} />;
      case 'HITL':      return <HITLTab   {...tabProps} />;
      case 'Knowledge': return <Knowledge {...tabProps} />;
      case 'Comms':     return <Comms     {...tabProps} />;
      case 'Alerts':    return <AlertsTab {...tabProps} />;
      default:          return <Overview  {...tabProps} />;
    }
  };

  return (
    <div style={{ minHeight:'100vh' }}>
      <Header data={data} connected={connected} lastUpdated={lastUpdated} updateCount={updateCount} />
      <Nav tabs={TABS} active={activeTab} onChange={setActiveTab} badges={badges} />
      <main style={{ padding:16 }}>
        {renderTab()}
      </main>
    </div>
  );
}

export default function AgentMiniCard({ agent: a }) {
  const dotCls = { active:'dot-active', available:'dot-available', busy:'dot-busy', error:'dot-error' }[a.status] || 'dot-offline';
  return (
    <div className="card" style={{ padding: 10 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
        <span style={{ fontSize: 18 }}>{a.emoji || '🤖'}</span>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 600, fontSize: 12, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{a.name}</div>
          <div style={{ color: 'var(--muted)', fontSize: 10 }}>{a.role}</div>
        </div>
        {a.inbox_count > 0 && (
          <span style={{ fontSize: 10, color: 'var(--amber)', fontWeight: 600 }}>📬{a.inbox_count}</span>
        )}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
        <span className={`dot ${dotCls}`} />
        <span style={{ fontSize: 10, color: 'var(--muted)', textTransform: 'capitalize' }}>{a.status}</span>
        <span style={{ marginLeft: 'auto', fontSize: 10, color: 'var(--muted)' }}>
          ⭐{(a.avg_quality || 0).toFixed(1)}
        </span>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

function Clock() {
  const [t, setT] = useState(new Date());
  useEffect(() => { const id = setInterval(() => setT(new Date()), 1000); return () => clearInterval(id); }, []);
  return <span style={{ color: 'var(--muted)', fontSize: 11 }}>{t.toLocaleTimeString()}</span>;
}

export default function Header({ data, connected, lastUpdated, updateCount }) {
  const agents  = data?.agents || [];
  const tc      = data?.task_counts || {};
  const budget  = data?.budget || {};
  const limits  = budget.limits  || {};
  const current = budget.current || {};
  const spent   = current.daily_usd ?? 0;
  const limit   = limits.daily_usd ?? 0;
  const pct     = limit > 0 ? Math.min(100, (spent / limit) * 100) : 0;
  const online  = agents.filter(a => ['active','available','busy'].includes(a.status)).length;

  // Gateway is truly live only if SSE is connected AND gateway_online flag from backend
  const gatewayOnline = connected && (data?.gateway_online !== false);
  const statusLabel   = !connected ? 'OFFLINE' : data?.gateway_online === false ? 'NO GATEWAY' : 'LIVE';
  const statusColor   = !connected ? 'var(--red)' : data?.gateway_online === false ? 'var(--amber)' : 'var(--green)';
  const dotClass      = !connected ? 'dot-error' : data?.gateway_online === false ? 'dot-busy' : 'dot-active';

  return (
    <header style={{
      height: 52, background: 'var(--bg2)', borderBottom: '1px solid var(--border)',
      display: 'flex', alignItems: 'center', padding: '0 16px', gap: 20,
      position: 'sticky', top: 0, zIndex: 100,
    }}>
      {/* Brand */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, minWidth: 160 }}>
        <span style={{ fontSize: 18 }}>🦅</span>
        <span style={{ fontFamily: 'Rajdhani, sans-serif', fontWeight: 700, fontSize: 16, color: 'var(--cyan)', letterSpacing: 1 }}>
          AGI Ops Room
        </span>
      </div>

      {/* Status badge */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 6 }} title={data?.gateway_online === false ? 'OpenClaw gateway unreachable' : ''}>
        <span className={`dot ${dotClass}`} />
        <span style={{ fontSize: 10, fontWeight: 600, color: statusColor }}>{statusLabel}</span>
      </div>

      <div style={{ width: 1, height: 20, background: 'var(--border)' }} />

      <Stat label="Online"   value={`${online}/${agents.length}`} color="var(--cyan)" />
      <Stat label="Pending"  value={tc.pending ?? 0}              color="var(--amber)" />
      <Stat label="HITL 🚨"  value={tc.needs_human_decision ?? 0} color="var(--purple)" alert={(tc.needs_human_decision ?? 0) > 0} />
      <Stat label="Budget"   value={`$${spent.toFixed(2)}/$${limit}`}
            color={pct > (budget.alerts?.daily_threshold_pct ?? 70) ? 'var(--red)' : 'var(--green)'} />

      <div style={{ flex: 1 }} />

      {updateCount > 0 && (
        <span style={{ fontSize: 9, color: 'var(--cyan)', opacity: 0.5 }}>#{updateCount}</span>
      )}
      {lastUpdated && (
        <span style={{ fontSize: 10, color: 'var(--muted)' }}>↻ {lastUpdated.toLocaleTimeString()}</span>
      )}
      <Clock />
    </header>
  );
}

function Stat({ label, value, color, alert }) {
  return (
    <div style={{ textAlign: 'center' }}>
      <div style={{ fontSize: 9, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '.06em' }}>{label}</div>
      <div style={{ fontSize: 14, fontWeight: 700, color: alert ? 'var(--red)' : color }}>{value}</div>
    </div>
  );
}

export default function LastUpdated({ ts, count }) {
  if (!ts) return null;
  return (
    <span style={{ fontSize: 9, color: 'var(--muted)', marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 6 }}>
      {count != null && <span style={{ color: 'var(--cyan)', opacity: 0.6 }}>#{count}</span>}
      ↻ {ts.toLocaleTimeString()}
    </span>
  );
}

const BADGE_COLOR = { 'HITL': 'var(--red)', 'Alerts': 'var(--red)', 'Crons': 'var(--amber)' };

export default function Nav({ tabs, active, onChange, badges = {} }) {
