import { useState } from 'react';
import LastUpdated from '../LastUpdated';

const SEV_COLOR  = { critical: 'var(--red)', high: 'var(--red)', medium: 'var(--amber)', low: 'var(--muted)' };
const TYPE_ICON  = { hitl: '🚨', sla_breach: '⏰', agent_error: '🔴', cron_error: '⚙️', blocked: '🚫' };
const TYPE_LABEL = { hitl: 'HITL', sla_breach: 'SLA', agent_error: 'Agent', cron_error: 'Cron', blocked: 'Blocked' };

function relTime(iso) {
  if (!iso) return '';
  try {
    const diff = Math.round((Date.now() - new Date(iso)) / 60000);
    if (diff < 1) return 'just now';
    if (diff < 60) return `${diff}m ago`;
    return `${Math.round(diff / 60)}h ago`;
  } catch { return ''; }
}

export default function AlertsTab({ data, lastUpdated }) {
  const { alerts = [], agents = [] } = data;
  const [dismissed, setDismissed] = useState(new Set());
  const [typeFilter, setTypeFilter] = useState('all');

  const active = alerts.filter(a => !dismissed.has(a.id));
  const filtered = active.filter(a => typeFilter === 'all' || a.type === typeFilter);

  const types = ['all', ...new Set(alerts.map(a => a.type))];
  const bySev = { critical: 0, high: 0, medium: 0, low: 0 };
  active.forEach(a => { if (bySev[a.severity] !== undefined) bySev[a.severity]++; });

  return (
    <div className="fade-in" style={{ display: 'grid', gap: 14 }}>
      {/* Summary */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 10 }}>
        {Object.entries(bySev).map(([sev, count]) => (
          <div key={sev} className="card" style={{ textAlign: 'center' }}>
            <div className="section-title" style={{ textTransform: 'capitalize' }}>{sev}</div>
            <div style={{ fontSize: 22, fontWeight: 700, color: count ? SEV_COLOR[sev] : 'var(--muted)' }}>{count}</div>
          </div>
        ))}
      </div>

      {/* Filters + header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
        {types.map(t => (
          <button key={t} onClick={() => setTypeFilter(t)} style={{
            background: typeFilter === t ? 'rgba(0,229,255,.15)' : 'var(--surface)',
            border: `1px solid ${typeFilter === t ? 'rgba(0,229,255,.4)' : 'var(--border)'}`,
            color: typeFilter === t ? 'var(--cyan)' : 'var(--muted)',
            padding: '4px 12px', borderRadius: 4, fontSize: 11, cursor: 'pointer', fontFamily: 'inherit',
          }}>{TYPE_ICON[t] || ''} {TYPE_LABEL[t] || t}</button>
        ))}
        {dismissed.size > 0 && (
          <button onClick={() => setDismissed(new Set())} style={{
            marginLeft: 'auto', background: 'none', border: '1px solid var(--border)',
            color: 'var(--muted)', padding: '4px 10px', borderRadius: 4, fontSize: 11,
            cursor: 'pointer', fontFamily: 'inherit',
          }}>↺ Restore {dismissed.size} dismissed</button>
        )}
        <LastUpdated ts={lastUpdated} />
      </div>

      {/* Alert list */}
      {filtered.length === 0 && (
        <div className="card" style={{ color: 'var(--green)', fontSize: 13 }}>
          ✅ {alerts.length === 0 ? 'No alerts — all systems nominal.' : 'All alerts dismissed for this session.'}
        </div>
      )}

      {filtered.map(alert => {
        const color = SEV_COLOR[alert.severity] || 'var(--muted)';
        const agent = agents.find(a => a.id === alert.agent_id);
        return (
          <div key={alert.id} style={{
            background: 'var(--bg2)', borderRadius: 8,
            border: `1px solid ${color}44`,
            boxShadow: `0 0 12px ${color}0d`,
            display: 'flex', gap: 14, padding: '14px 16px', alignItems: 'flex-start',
          }}>
            <span style={{ fontSize: 22, flexShrink: 0 }}>{TYPE_ICON[alert.type] || '⚠️'}</span>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4, flexWrap: 'wrap' }}>
                <span style={{ fontWeight: 700, fontSize: 13 }}>{alert.title}</span>
                <span style={{ fontSize: 10, padding: '1px 6px', borderRadius: 3, fontWeight: 700,
                  textTransform: 'uppercase', color, background: `${color}18`, border: `1px solid ${color}44` }}>
                  {alert.severity}
                </span>
              </div>
              {alert.detail && <div style={{ fontSize: 12, color: 'var(--muted)', lineHeight: 1.5, marginBottom: 4 }}>{alert.detail}</div>}
              <div style={{ fontSize: 10, color: 'var(--muted)', display: 'flex', gap: 10 }}>
                {agent && <span>{agent.emoji} {agent.name}</span>}
                <span>{TYPE_LABEL[alert.type]}</span>
                <span>{relTime(alert.ts)}</span>
                {alert.task_id && <span style={{ color: 'var(--cyan)' }}>{alert.task_id}</span>}
                {alert.cron_id && <span style={{ color: 'var(--cyan)', fontFamily: 'monospace', fontSize: 9 }}>{alert.cron_id.slice(0, 8)}…</span>}
              </div>
            </div>
            <button onClick={() => setDismissed(prev => new Set([...prev, alert.id]))}
              title="Dismiss alert" style={{
                background: 'none', border: '1px solid var(--border)', color: 'var(--muted)',
                padding: '3px 8px', borderRadius: 4, cursor: 'pointer', fontSize: 10, fontFamily: 'inherit', flexShrink: 0,
              }}>✕</button>
          </div>
        );
      })}
    </div>
  );
}

import { useEffect, useRef } from 'react';

export default function Broadcast({ data }) {
  const { broadcast = '' } = data;
  const ref = useRef(null);

  useEffect(() => {
    if (ref.current) ref.current.scrollTop = ref.current.scrollHeight;
  }, [broadcast]);

  const lines = broadcast.split('\n');

  return (
    <div className="fade-in">
      <div style={{
        background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 8,
        padding: 16, fontFamily: 'JetBrains Mono, monospace', fontSize: 12,
        height: 'calc(100vh - 160px)', overflowY: 'auto',
      }} ref={ref}>
        {lines.length === 0 || broadcast.trim() === ''
          ? <span style={{ color: 'var(--muted)' }}>No broadcasts yet.</span>
          : lines.map((line, i) => <BroadcastLine key={i} line={line} />)
        }
        <div style={{ height: 8 }} />
      </div>
    </div>
  );
}

function BroadcastLine({ line }) {
  const low = line.toLowerCase();
  let color = 'var(--text)';
  if (low.includes('[critical]') || low.includes('🔴'))   color = 'var(--red)';
  else if (low.includes('[blocked]') || low.includes('⚠')) color = 'var(--amber)';
  else if (low.includes('[hitl]')    || low.includes('🚨')) color = 'var(--purple)';
  else if (low.includes('[done]')    || low.includes('✅')) color = 'var(--green)';
  else if (line.startsWith('#'))                           color = 'var(--cyan)';
  else if (line.startsWith('---'))                        color = 'rgba(84,110,122,.5)';
  else if (low.includes('task_id:') || low.includes('from:')) color = 'var(--muted)';

  return (
    <div style={{
      color, padding: '1px 0', lineHeight: 1.6, whiteSpace: 'pre-wrap', wordBreak: 'break-word',
    }}>
      {line || '\u00A0'}
    </div>
  );
}

import LastUpdated from '../LastUpdated';

export default function Budget({ data, lastUpdated }) {
  const { budget = {} } = data;
  const limits      = budget.limits  || {};
  const current     = budget.current || {};
  const alerts      = budget.alerts  || {};
  const byAgent     = budget.per_agent || {};
  const byModel     = budget.per_model || {};
  const notes       = budget.notes || null;
  const lastUpdatedData = budget.last_updated || null;

  const periods = [
    { label: 'Daily',   spent: current.daily_usd   ?? 0, limit: limits.daily_usd   ?? 0, threshold: alerts.daily_threshold_pct   ?? 70 },
    { label: 'Weekly',  spent: current.weekly_usd  ?? 0, limit: limits.weekly_usd  ?? 0, threshold: alerts.weekly_threshold_pct  ?? 70 },
    { label: 'Monthly', spent: current.monthly_usd ?? 0, limit: limits.monthly_usd ?? 0, threshold: 80 },
  ];

  return (
    <div className="fade-in" style={{ display: 'grid', gap: 14 }}>

      {/* Notes banner */}
      {notes && (
        <div style={{ padding: '10px 14px', background: 'rgba(255,214,0,.07)', border: '1px solid rgba(255,214,0,.25)',
          borderRadius: 6, fontSize: 11, color: 'var(--amber)', display: 'flex', alignItems: 'flex-start', gap: 8 }}>
          <span>⚠</span>
          <div>
            <span>{notes}</span>
            {lastUpdatedData && (
              <span style={{ color: 'var(--muted)', marginLeft: 12 }}>
                Last updated: {new Date(lastUpdatedData).toLocaleString()}
              </span>
            )}
          </div>
          <LastUpdated ts={lastUpdated} />
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 14 }}>
        {periods.map(({ label, spent, limit, threshold }) => {
          const pct = limit > 0 ? Math.min(100, (spent / limit) * 100) : 0;
          const over = pct >= threshold;
          return (
            <div key={label} className="card">
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                <span className="section-title">{label}</span>
                <span style={{ fontSize: 11, fontWeight: 700, color: over ? 'var(--red)' : 'var(--cyan)' }}>
                  ${spent.toFixed(2)} / ${limit}
                </span>
              </div>
              {/* Progress with threshold marker */}
              <div className="progress-track" style={{ position: 'relative' }}>
                <div className="progress-fill" style={{
                  width: `${pct}%`,
                  background: pct > threshold ? 'var(--red)' : pct > threshold * 0.8 ? 'var(--amber)' : 'var(--cyan)',
                }} />
                {/* Threshold marker */}
                <div style={{
                  position: 'absolute', top: -2, bottom: -2,
                  left: `${threshold}%`, width: 1,
                  background: 'var(--amber)', opacity: 0.6,
                }} />
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 4, fontSize: 10, color: 'var(--muted)' }}>
                <span>{pct.toFixed(1)}% used</span>
                <span style={{ color: 'var(--amber)' }}>⚠ at {threshold}%</span>
              </div>
            </div>
          );
        })}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
        <BreakdownTable title="By Agent" data={byAgent} />
        <BreakdownTable title="By Model" data={byModel} />
      </div>
    </div>
  );
}

function BreakdownTable({ title, data }) {
  const entries = Object.entries(data).sort(([, a], [, b]) => {
    const sa = typeof a === 'object' ? (a.spent ?? 0) : a;
    const sb = typeof b === 'object' ? (b.spent ?? 0) : b;
    return sb - sa;
  });
  return (
    <div className="card">
      <div className="section-title">{title}</div>
      {entries.length === 0
        ? <div style={{ color: 'var(--muted)', fontSize: 11, paddingTop: 8 }}>No spend data yet</div>
        : <table style={{ width: '100%', fontSize: 11, borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '1px solid var(--border)' }}>
                <th style={{ textAlign: 'left',  padding: '4px 0', color: 'var(--muted)', fontSize: 10 }}>Name</th>
                <th style={{ textAlign: 'right', padding: '4px 0', color: 'var(--muted)', fontSize: 10 }}>Spent</th>
                <th style={{ textAlign: 'right', padding: '4px 0', color: 'var(--muted)', fontSize: 10 }}>Calls</th>
              </tr>
            </thead>
            <tbody>
              {entries.map(([name, v]) => {
                const spent = typeof v === 'object' ? (v.spent ?? 0) : v;
                const calls = typeof v === 'object' ? (v.calls ?? '—') : '—';
                return (
                  <tr key={name} style={{ borderBottom: '1px solid rgba(255,255,255,.03)' }}>
                    <td style={{ padding: '5px 0', maxWidth: 140, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{name}</td>
                    <td style={{ padding: '5px 0', textAlign: 'right', color: 'var(--cyan)', fontWeight: 600 }}>${spent.toFixed(3)}</td>
                    <td style={{ padding: '5px 0', textAlign: 'right', color: 'var(--muted)' }}>{calls}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
      }
    </div>
  );
}

import { useState } from 'react';
import LastUpdated from '../LastUpdated';

function CommsPanel({ content, label, color }) {
  if (!content || content.trim() === '' || content.trim() === `# ${label}\n\n_No messages._`) {
    return <div style={{ color: 'var(--muted)', fontSize: 11, padding: '8px 0' }}>No {label.toLowerCase()} messages.</div>;
  }

  const lines = content.split('\n');
  return (
    <div style={{ fontFamily: 'monospace', fontSize: 11, lineHeight: 1.7, maxHeight: 400, overflowY: 'auto' }}>
      {lines.map((line, i) => {
        let lineColor = 'var(--text)';
        if (line.startsWith('## '))      lineColor = color;
        else if (line.startsWith('# '))  lineColor = color;
        else if (line.startsWith('---')) lineColor = 'rgba(255,255,255,.1)';
        else if (line.startsWith('- '))  lineColor = 'var(--muted)';
        else if (line.startsWith('**'))  lineColor = 'var(--amber)';
        return (
          <div key={i} style={{ color: lineColor, padding: '1px 0',
            borderBottom: line.startsWith('---') ? '1px solid rgba(255,255,255,.06)' : 'none' }}>
            {line || '\u00A0'}
          </div>
        );
      })}
    </div>
  );
}

export default function Comms({ data, lastUpdated }) {
  const { comms = {}, agents = [] } = data;
  const [selectedAgent, setSelectedAgent] = useState(agents[0]?.id || null);
  const [view, setView] = useState('inbox');

  const agentComms = comms[selectedAgent] || { inbox: '', outbox: '' };
  const agent = agents.find(a => a.id === selectedAgent);

  // Count messages per agent
  const countMessages = (text) => (text?.match(/^## /gm) || []).length;

  return (
    <div className="fade-in" style={{ display: 'grid', gridTemplateColumns: '200px 1fr', gap: 14, minHeight: 500 }}>
      {/* Agent selector */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
        <div className="section-title">Agents</div>
        {agents.map(a => {
          const ac = comms[a.id] || {};
          const inboxCount = countMessages(ac.inbox);
          const outboxCount = countMessages(ac.outbox);
          return (
            <button key={a.id} onClick={() => setSelectedAgent(a.id)} style={{
              background: selectedAgent === a.id ? 'rgba(0,229,255,.12)' : 'var(--surface)',
              border: `1px solid ${selectedAgent === a.id ? 'rgba(0,229,255,.4)' : 'var(--border)'}`,
              borderRadius: 6, padding: '8px 10px', cursor: 'pointer', textAlign: 'left',
              display: 'flex', alignItems: 'center', gap: 8, fontFamily: 'inherit',
            }}>
              <span style={{ fontSize: 18 }}>{a.emoji}</span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 12, fontWeight: 600, color: selectedAgent === a.id ? 'var(--cyan)' : 'var(--text)',
                  overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{a.name}</div>
                <div style={{ fontSize: 10, color: 'var(--muted)' }}>
                  📬{inboxCount} · 📤{outboxCount}
                </div>
              </div>
            </button>
          );
        })}
      </div>

      {/* Comms viewer */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          {agent && <span style={{ fontSize: 20 }}>{agent.emoji}</span>}
          {agent && <span style={{ fontWeight: 700, fontSize: 14 }}>{agent.name}</span>}
          <div style={{ display: 'flex', gap: 4, marginLeft: 8 }}>
            {['inbox','outbox'].map(v => (
              <button key={v} onClick={() => setView(v)} style={{
                background: view === v ? 'rgba(0,229,255,.15)' : 'var(--surface)',
                border: `1px solid ${view === v ? 'rgba(0,229,255,.4)' : 'var(--border)'}`,
                color: view === v ? 'var(--cyan)' : 'var(--muted)',
                padding: '4px 12px', borderRadius: 4, fontSize: 11, cursor: 'pointer', fontFamily: 'inherit',
                textTransform: 'capitalize',
              }}>{v === 'inbox' ? '📬' : '📤'} {v}</button>
            ))}
          </div>
          <LastUpdated ts={lastUpdated} />
        </div>

        <div className="card" style={{ flex: 1 }}>
          <CommsPanel
            content={agentComms[view]}
            label={view === 'inbox' ? 'Inbox' : 'Outbox'}
            color={view === 'inbox' ? 'var(--cyan)' : 'var(--green)'}
          />
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import LastUpdated from '../LastUpdated';

async function apiPost(path) {
  const r = await fetch(path, { method: 'POST', headers: { 'Content-Type': 'application/json' } });
  return r.json();
}

function fmtDuration(ms) {
  if (!ms) return '—';
  if (ms < 1000) return `${ms}ms`;
  if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`;
  return `${Math.round(ms / 60000)}m ${Math.round((ms % 60000) / 1000)}s`;
}

function fmtNext(sec) {
  if (sec === null || sec === undefined) return '—';
  if (sec < 0) return 'overdue';
  if (sec < 60) return `${sec}s`;
  if (sec < 3600) return `${Math.round(sec / 60)}m`;
  return `${Math.round(sec / 3600)}h`;
}

function fmtLast(sec) {
  if (sec === null || sec === undefined) return '—';
  if (sec < 60) return `${sec}s ago`;
  if (sec < 3600) return `${Math.round(sec / 60)}m ago`;
  return `${Math.round(sec / 3600)}h ago`;
}

function StatusDot({ status, errors }) {
  if (errors >= 3) return <span className="dot dot-error" title={`${errors} consecutive errors`} />;
  if (status === 'error') return <span className="dot dot-error" />;
  if (status === 'running') return <span className="dot dot-active" />;
  if (status === 'ok') return <span className="dot dot-available" />;
  return <span className="dot dot-offline" />;
}

function CronRow({ job, agents, onTrigger, onToggle }) {
  const [triggering, setTriggering] = useState(false);
  const [toggling, setToggling] = useState(false);
  const [localEnabled, setLocalEnabled] = useState(job.enabled !== false);
  const agent = agents.find(a => a.id === job.agentId);
  const errors = job._consecutive_errors || 0;
  const isError = errors >= 3 || job._status === 'error';

  async function trigger() {
    setTriggering(true);
    await apiPost(`/api/cron/${job.id}/trigger`);
    onTrigger?.(job.id);
    setTimeout(() => setTriggering(false), 2000);
  }

  async function toggle() {
    setToggling(true);
    const res = await apiPost(`/api/cron/${job.id}/toggle`);
    if (res.ok) setLocalEnabled(res.enabled);
    setToggling(false);
    onToggle?.(job.id, res.enabled);
  }

  return (
    <>
      <tr style={{
        borderBottom: '1px solid rgba(255,255,255,.03)',
        background: isError ? 'rgba(255,23,68,.03)' : 'transparent',
        opacity: localEnabled ? 1 : 0.5,
      }}>
        <td style={{ padding: '8px 12px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <StatusDot status={job._status} errors={errors} />
            <div>
              <div style={{ fontSize: 12, fontWeight: errors >= 3 ? 700 : 400,
                color: isError ? 'var(--red)' : 'var(--text)' }}>{job.name}</div>
              {job.description && <div style={{ fontSize: 10, color: 'var(--muted)' }}>{job.description.slice(0, 60)}</div>}
            </div>
          </div>
        </td>
        <td style={{ padding: '8px 12px', fontSize: 11 }}>
          {agent ? <span>{agent.emoji} {agent.name}</span> : <span style={{ color: 'var(--muted)' }}>{job.agentId}</span>}
        </td>
        <td style={{ padding: '8px 12px', fontSize: 10, color: 'var(--muted)', fontFamily: 'monospace' }}>
          {job.schedule?.kind === 'every'
            ? `every ${Math.round((job.schedule.everyMs || 0) / 60000)}m`
            : (job.schedule?.cronExpression || job.schedule?.kind || '—')}
        </td>
        <td style={{ padding: '8px 12px', fontSize: 11, color: fmtNext(job._next_run_sec) === 'overdue' ? 'var(--red)' : 'var(--muted)' }}>
          {fmtNext(job._next_run_sec)}
        </td>
        <td style={{ padding: '8px 12px', fontSize: 11, color: 'var(--muted)' }}>
          {fmtLast(job._last_run_sec)}
        </td>
        <td style={{ padding: '8px 12px', fontSize: 11, color: 'var(--muted)' }}>
          {fmtDuration(job._duration_ms)}
        </td>
        <td style={{ padding: '8px 12px' }}>
          {isError && (
            <span style={{ fontSize: 10, padding: '2px 6px', borderRadius: 3, fontWeight: 700,
              background: 'rgba(255,23,68,.15)', color: 'var(--red)', border: '1px solid rgba(255,23,68,.3)' }}>
              {errors}× err
            </span>
          )}
          {!isError && job._status === 'ok' && (
            <span style={{ fontSize: 10, padding: '2px 6px', borderRadius: 3,
              background: 'rgba(0,230,118,.1)', color: 'var(--green)', border: '1px solid rgba(0,230,118,.25)' }}>ok</span>
          )}
        </td>
        <td style={{ padding: '8px 12px' }}>
          <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
            <button onClick={trigger} disabled={triggering} title="Trigger now" style={{
              background: 'rgba(0,229,255,.1)', border: '1px solid rgba(0,229,255,.3)',
              color: 'var(--cyan)', padding: '3px 8px', borderRadius: 4,
              cursor: triggering ? 'not-allowed' : 'pointer', fontSize: 10, fontFamily: 'inherit',
            }}>{triggering ? '...' : '▶ Run'}</button>
            <button onClick={toggle} disabled={toggling} title={localEnabled ? 'Disable' : 'Enable'} style={{
              background: localEnabled ? 'rgba(255,214,0,.08)' : 'rgba(0,230,118,.08)',
              border: `1px solid ${localEnabled ? 'rgba(255,214,0,.3)' : 'rgba(0,230,118,.3)'}`,
              color: localEnabled ? 'var(--amber)' : 'var(--green)',
              padding: '3px 8px', borderRadius: 4, cursor: toggling ? 'not-allowed' : 'pointer',
              fontSize: 10, fontFamily: 'inherit',
            }}>{toggling ? '...' : localEnabled ? '⏸ Off' : '▶ On'}</button>
          </div>
        </td>
      </tr>
      {isError && job._last_error && (
        <tr style={{ background: 'rgba(255,23,68,.04)' }}>
          <td colSpan={8} style={{ padding: '4px 12px 8px 40px', fontSize: 10, color: 'var(--red)', fontFamily: 'monospace' }}>
            ↳ {job._last_error}
          </td>
        </tr>
      )}
    </>
  );
}

export default function Crons({ data, lastUpdated }) {
  const { crons = [], agents = [] } = data;
  const [filter, setFilter] = useState('all');

  const erroring  = crons.filter(j => (j._consecutive_errors || 0) >= 3 || j._status === 'error');
  const running   = crons.filter(j => j._status === 'running');
  const disabled  = crons.filter(j => j.enabled === false);

  const filtered = crons.filter(j => {
    if (filter === 'error')   return (j._consecutive_errors || 0) >= 3 || j._status === 'error';
    if (filter === 'running') return j._status === 'running';
    if (filter === 'disabled') return j.enabled === false;
    return true;
  });

  // Group by agent
  const byAgent = {};
  filtered.forEach(j => {
    const a = j.agentId || 'unknown';
    if (!byAgent[a]) byAgent[a] = [];
    byAgent[a].push(j);
  });

  return (
    <div className="fade-in" style={{ display: 'grid', gap: 14 }}>
      {/* Summary */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 10 }}>
        {[
          ['Total', crons.length, 'var(--muted)'],
          ['Erroring', erroring.length, erroring.length ? 'var(--red)' : 'var(--muted)'],
          ['Running', running.length, running.length ? 'var(--cyan)' : 'var(--muted)'],
          ['Disabled', disabled.length, disabled.length ? 'var(--amber)' : 'var(--muted)'],
        ].map(([l, v, c]) => (
          <div key={l} className="card" style={{ textAlign: 'center', cursor: 'pointer' }}
            onClick={() => setFilter(l.toLowerCase())}>
            <div className="section-title">{l}</div>
            <div style={{ fontSize: 22, fontWeight: 700, color: c }}>{v}</div>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
        {['all','error','running','disabled'].map(f => (
          <button key={f} onClick={() => setFilter(f)} style={{
            background: filter === f ? 'rgba(0,229,255,.15)' : 'var(--surface)',
            border: `1px solid ${filter === f ? 'rgba(0,229,255,.4)' : 'var(--border)'}`,
            color: filter === f ? 'var(--cyan)' : 'var(--muted)',
            padding: '4px 12px', borderRadius: 4, fontSize: 11, cursor: 'pointer', fontFamily: 'inherit',
          }}>{f}</button>
        ))}
        <LastUpdated ts={lastUpdated} />
      </div>

      {/* Table */}
      <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
          <thead>
            <tr style={{ background: 'var(--bg3)', borderBottom: '1px solid var(--border)' }}>
              {['Job', 'Agent', 'Schedule', 'Next', 'Last Run', 'Duration', 'Status', 'Actions'].map(h => (
                <th key={h} style={{ padding: '8px 12px', textAlign: 'left', fontSize: 10,
                  color: 'var(--muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '.05em' }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.length === 0 && (
              <tr><td colSpan={8} style={{ padding: '20px', color: 'var(--muted)', textAlign: 'center' }}>No cron jobs match filter</td></tr>
            )}
            {filtered.map(j => (
              <CronRow key={j.id} job={j} agents={agents} />
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useState } from 'react';
import LastUpdated from '../LastUpdated';

async function apiPost(path, body = {}) {
  const r = await fetch(path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  return r.json();
}

function relTime(iso) {
  if (!iso) return '—';
  try {
    const diff = Math.round((Date.now() - new Date(iso)) / 60000);
    if (diff < 1) return 'just now';
    if (diff < 60) return `${diff}m ago`;
    if (diff < 1440) return `${Math.round(diff / 60)}h ago`;
    return `${Math.round(diff / 1440)}d ago`;
  } catch { return iso; }
}

function HITLCard({ task, agents, onAction }) {
  const [note, setNote] = useState('');
  const [loading, setLoading] = useState(null);
  const agent = agents.find(a => a.id === task.assigned_to);
  const waitTime = relTime(task.created_at);
  const pri = (task.sla?.priority || task.priority || '').toUpperCase();

  async function act(action) {
    setLoading(action);
    try {
      await apiPost(`/api/hitl/${task.id}/${action}`, { note: note || undefined });
      onAction(task.id, action);
    } catch (e) { console.error(e); }
    setLoading(null);
  }

  return (
    <div style={{
      background: 'var(--bg2)', border: '1px solid rgba(224,64,251,.35)',
      borderRadius: 10, padding: 18, display: 'grid', gap: 14,
      boxShadow: '0 0 20px rgba(224,64,251,.08)',
    }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12 }}>
        <span style={{ fontSize: 28 }}>🚨</span>
        <div style={{ flex: 1 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4, flexWrap: 'wrap' }}>
            <span style={{ fontWeight: 700, fontSize: 15 }}>{task.title}</span>
            <span style={{ fontSize: 10, fontFamily: 'monospace', color: 'var(--muted)' }}>{task.id}</span>
            {pri && <span className={pri === 'P1' ? 'p1' : pri === 'P2' ? 'p2' : 'p3'}>{pri}</span>}
          </div>
          <div style={{ fontSize: 11, color: 'var(--muted)' }}>
            {agent && <span>{agent.emoji} {agent.name} · </span>}
            Waiting <span style={{ color: 'var(--amber)', fontWeight: 600 }}>{waitTime}</span>
            {task.sla?.deadline && <span> · Due {new Date(task.sla.deadline).toLocaleString()}</span>}
          </div>
        </div>
      </div>

      {/* HITL Reason */}
      <div style={{ padding: '12px 14px', background: 'rgba(224,64,251,.08)', border: '1px solid rgba(224,64,251,.25)', borderRadius: 7 }}>
        <div style={{ fontSize: 10, color: 'var(--purple)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.06em', marginBottom: 6 }}>Decision Required</div>
        <div style={{ fontSize: 13, color: 'var(--text)', lineHeight: 1.6 }}>{task.hitl_reason || 'Human decision required before proceeding.'}</div>
      </div>

      {/* Description */}
      {task.description && (
        <div>
          <div style={{ fontSize: 10, color: 'var(--muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '.05em', marginBottom: 4 }}>Context</div>
          <div style={{ fontSize: 12, color: 'var(--text)', lineHeight: 1.6 }}>{task.description}</div>
        </div>
      )}

      {/* Note input */}
      <div>
        <div style={{ fontSize: 10, color: 'var(--muted)', marginBottom: 6 }}>Optional note (sent to agent)</div>
        <input value={note} onChange={e => setNote(e.target.value)}
          placeholder="Add context for the agent..."
          style={{ width: '100%', background: 'var(--bg3)', border: '1px solid var(--border)', borderRadius: 5,
            padding: '8px 10px', fontSize: 12, color: 'var(--text)', fontFamily: 'inherit', outline: 'none',
            boxSizing: 'border-box' }} />
      </div>

      {/* Action buttons */}
      <div style={{ display: 'flex', gap: 10 }}>
        <button onClick={() => act('approve')} disabled={!!loading} style={{
          flex: 1, padding: '10px', background: 'rgba(0,230,118,.15)', border: '1px solid rgba(0,230,118,.4)',
          color: 'var(--green)', borderRadius: 6, cursor: loading ? 'not-allowed' : 'pointer',
          fontFamily: 'inherit', fontSize: 13, fontWeight: 700, transition: 'all .15s',
        }}>
          {loading === 'approve' ? '...' : '✅ Approve — Continue'}
        </button>
        <button onClick={() => act('reject')} disabled={!!loading} style={{
          flex: 1, padding: '10px', background: 'rgba(255,23,68,.1)', border: '1px solid rgba(255,23,68,.35)',
          color: 'var(--red)', borderRadius: 6, cursor: loading ? 'not-allowed' : 'pointer',
          fontFamily: 'inherit', fontSize: 13, fontWeight: 700, transition: 'all .15s',
        }}>
          {loading === 'reject' ? '...' : '❌ Reject — Block Task'}
        </button>
      </div>
    </div>
  );
}

export default function HITLTab({ data, lastUpdated }) {
  const { hitl_tasks = [], agents = [] } = data;
  const [resolved, setResolved] = useState(new Set());

  const pending = hitl_tasks.filter(t => !resolved.has(t.id));

  function onAction(taskId) {
    setResolved(prev => new Set([...prev, taskId]));
  }

  return (
    <div className="fade-in" style={{ display: 'grid', gap: 14 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <span style={{ fontSize: 14, fontWeight: 700, color: pending.length ? 'var(--red)' : 'var(--green)' }}>
          {pending.length ? `🚨 ${pending.length} decision${pending.length > 1 ? 's' : ''} awaiting your input` : '✅ No pending HITL decisions'}
        </span>
        <LastUpdated ts={lastUpdated} />
      </div>

      {pending.length === 0 && (
        <div className="card" style={{ color: 'var(--muted)', fontSize: 13 }}>
          All clear — no human decisions required right now. Agents are running autonomously.
        </div>
      )}

      {pending.map(t => (
        <HITLCard key={t.id} task={t} agents={agents} onAction={onAction} />
      ))}

      {resolved.size > 0 && (
        <div style={{ padding: '10px 14px', background: 'rgba(0,230,118,.06)', border: '1px solid rgba(0,230,118,.2)', borderRadius: 6, fontSize: 12, color: 'var(--green)' }}>
          ✅ {resolved.size} decision{resolved.size > 1 ? 's' : ''} resolved this session — agents notified via task status update.
        </div>
      )}
    </div>
  );
}

import { useState, useMemo } from 'react';
import LastUpdated from '../LastUpdated';

export default function Knowledge({ data, lastUpdated }) {
  const { knowledge = [], agents = [] } = data;
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('all');

  const categories = useMemo(() => {
    const cats = new Set(knowledge.map(e => e.category || 'general'));
    return ['all', ...Array.from(cats).sort()];
  }, [knowledge]);

  const filtered = useMemo(() => {
    return knowledge.filter(e => {
      const matchCat = category === 'all' || (e.category || 'general') === category;
      const q = search.toLowerCase();
      const matchSearch = !q || (e.content || e.summary || '').toLowerCase().includes(q)
        || (e.title || '').toLowerCase().includes(q)
        || (e.tags || []).some(t => t.toLowerCase().includes(q));
      return matchCat && matchSearch;
    });
  }, [knowledge, search, category]);

  return (
    <div className="fade-in" style={{ display: 'grid', gap: 14 }}>
      {/* Search + filter */}
      <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
        <input value={search} onChange={e => setSearch(e.target.value)}
          placeholder="Search knowledge base..."
          style={{ flex: 1, minWidth: 200, background: 'var(--bg3)', border: '1px solid var(--border)',
            borderRadius: 5, padding: '7px 12px', fontSize: 12, color: 'var(--text)',
            fontFamily: 'inherit', outline: 'none' }} />
        {categories.map(c => (
          <button key={c} onClick={() => setCategory(c)} style={{
            background: category === c ? 'rgba(0,229,255,.15)' : 'var(--surface)',
            border: `1px solid ${category === c ? 'rgba(0,229,255,.4)' : 'var(--border)'}`,
            color: category === c ? 'var(--cyan)' : 'var(--muted)',
            padding: '5px 12px', borderRadius: 4, fontSize: 11, cursor: 'pointer', fontFamily: 'inherit',
            textTransform: 'capitalize',
          }}>{c}</button>
        ))}
        <LastUpdated ts={lastUpdated} />
      </div>

      <div style={{ fontSize: 11, color: 'var(--muted)' }}>
        {filtered.length} / {knowledge.length} entries
        {knowledge.length === 0 && ' — Cipher will populate this during synthesis crons'}
      </div>

      {/* Entries */}
      {filtered.length === 0 && (
        <div className="card" style={{ color: 'var(--muted)', fontSize: 13 }}>
          {knowledge.length === 0
            ? 'Knowledge base is empty. Cipher\'s synthesis cron populates SHARED_KNOWLEDGE.json every 6 hours.'
            : 'No entries match your search.'}
        </div>
      )}

      <div style={{ display: 'grid', gap: 10 }}>
        {filtered.map((entry, i) => {
          const agent = agents.find(a => a.id === entry.added_by || a.id === entry.author);
          return (
            <div key={entry.id || i} className="card">
              <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10, marginBottom: 8 }}>
                <div style={{ flex: 1 }}>
                  {entry.title && <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 4 }}>{entry.title}</div>}
                  <div style={{ fontSize: 12, color: 'var(--text)', lineHeight: 1.6 }}>
                    {entry.content || entry.summary || entry.insight || '—'}
                  </div>
                </div>
                <span style={{ fontSize: 10, padding: '2px 7px', borderRadius: 3, flexShrink: 0,
                  background: 'rgba(0,229,255,.07)', color: 'var(--cyan)', border: '1px solid rgba(0,229,255,.2)',
                  textTransform: 'capitalize' }}>{entry.category || 'general'}</span>
              </div>

              {entry.tags?.length > 0 && (
                <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap', marginBottom: 8 }}>
                  {entry.tags.map(t => (
                    <span key={t} style={{ fontSize: 9, padding: '1px 5px', borderRadius: 3,
                      background: 'rgba(255,214,0,.08)', color: 'var(--amber)', border: '1px solid rgba(255,214,0,.2)' }}>{t}</span>
                  ))}
                </div>
              )}

              <div style={{ fontSize: 10, color: 'var(--muted)', display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                {agent && <span>{agent.emoji} {agent.name}</span>}
                {entry.source_task && <span>Task: <span style={{ color: 'var(--cyan)' }}>{entry.source_task}</span></span>}
                {entry.added_at && <span>{new Date(entry.added_at).toLocaleString()}</span>}
                {entry.confidence && <span>Confidence: {Math.round(entry.confidence * 100)}%</span>}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import LastUpdated from '../LastUpdated';

export default function OKRs({ data, lastUpdated }) {
  const okrs = data.okrs || {};
  const objectives = okrs.objectives || okrs.okrs || [];

  return (
    <div className="fade-in" style={{ display: 'grid', gap: 14 }}>
      <div style={{ display: 'flex', alignItems: 'center', marginBottom: 2 }}>
        <span style={{ fontSize: 10, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '.08em' }}>
          {okrs.quarter || 'OKRs'}
        </span>
        <LastUpdated ts={lastUpdated} />
      </div>

      {objectives.length === 0 && (
        <div className="card" style={{ color: 'var(--muted)', fontSize: 13 }}>
          No OKRs defined yet. Add objectives to <code>OKRs.json</code> in your workspace.
        </div>
      )}

      {objectives.map((obj, i) => (
        <div key={obj.id || i} className="card">
          <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14, color: 'var(--cyan)' }}>
            {obj.objective || obj.title || `Objective ${i + 1}`}
          </div>

          {(obj.key_results || obj.krs || []).map((kr, j) => {
            const current = kr.current ?? 0;
            const target  = kr.target  ?? 100;
            const pct     = target > 0 ? Math.min(100, (current / target) * 100) : 0;
            const unit    = kr.unit ? ` ${kr.unit}` : '';
            return (
              <div key={kr.id || j} style={{
                marginBottom: 14, paddingLeft: 12,
                borderLeft: '2px solid rgba(0,229,255,.2)',
              }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 5 }}>
                  <span style={{ fontSize: 12, flex: 1, paddingRight: 12 }}>
                    {kr.result || kr.title || kr.description || `KR ${j + 1}`}
                  </span>
                  <span style={{ fontSize: 11, fontWeight: 600, whiteSpace: 'nowrap',
                    color: pct >= 100 ? 'var(--green)' : 'var(--amber)' }}>
                    {current} / {target}{unit}
                  </span>
                </div>
                <div className="progress-track">
                  <div className="progress-fill" style={{
                    width: `${pct}%`,
                    background: pct >= 100 ? 'var(--green)' : pct >= 70 ? 'var(--cyan)' : pct >= 40 ? 'var(--amber)' : 'var(--red)',
                  }} />
                </div>
                <div style={{ fontSize: 10, color: 'var(--muted)', marginTop: 3 }}>{pct.toFixed(0)}%</div>
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
}

