                  <span style={{ flex:1, fontSize:11, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{item.title || item.description || '—'}</span>
                  <span style={{ fontSize:10, color:'var(--muted)' }}>{item.category || item.type || ''}</span>
