#  HTTP HANDLER
# ═══════════════════════════════════════════════════════════════════════════════

SKILL_DIR = Path(__file__).parent


def make_handler(workspace: Path, broadcaster: Broadcaster):

    class DashboardHandler(BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"

        def log_message(self, fmt, *args):
            pass  # suppress default access log noise

        def send_cors(self):
            self.send_header("Access-Control-Allow-Origin",  "*")
            self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
            self.send_header("Access-Control-Allow-Headers", "Content-Type")

        def do_OPTIONS(self):
            self.send_response(200)
            self.send_cors()
            self.end_headers()

        def do_POST(self):
            path = self.path.split("?")[0]
            try:
                length = int(self.headers.get("Content-Length", 0))
                body   = json.loads(self.rfile.read(length)) if length else {}
            except Exception:
                body = {}

            def reply(data, status=200):
                b = json.dumps(data, default=str).encode("utf-8")
                self.send_response(status)
                self.send_header("Content-Type", "application/json")
                self.send_cors()
                self.send_header("Content-Length", str(len(b)))
                self.end_headers()
                self.wfile.write(b)

            # ── Cron trigger ──
            if path.startswith("/api/cron/") and path.endswith("/trigger"):
                cron_id = path.split("/")[3]
                try:
                    subprocess.Popen(["openclaw", "cron", "run", cron_id],
                                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                    reply({"ok": True, "cron_id": cron_id, "action": "triggered"})
                except Exception as e:
                    reply({"ok": False, "error": str(e)}, 500)

            # ── Cron toggle enable/disable ──
            elif path.startswith("/api/cron/") and path.endswith("/toggle"):
                cron_id = path.split("/")[3]
                try:
                    cron_file = Path.home() / ".openclaw/cron/jobs.json"
                    jobs_data = json.loads(cron_file.read_text())
                    for j in jobs_data.get("jobs", []):
                        if j["id"] == cron_id:
                            j["enabled"] = not j.get("enabled", True)
                            new_state    = j["enabled"]
                            break
                    cron_file.write_text(json.dumps(jobs_data, indent=2))
                    reply({"ok": True, "cron_id": cron_id, "enabled": new_state})
                    broadcaster.broadcast(get_dashboard_data(workspace))
                except Exception as e:
                    reply({"ok": False, "error": str(e)}, 500)

            # ── Task status update ──
            elif path.startswith("/api/task/") and path.endswith("/status"):
                task_id = path.split("/")[3]
                new_status = body.get("status")
                if not new_status:
                    reply({"ok": False, "error": "status required"}, 400)
                else:
                    try:
                        tasks_file = workspace / "TASKS.json"
                        tasks_data = json.loads(tasks_file.read_text())
                        task_list  = tasks_data.get("tasks", tasks_data if isinstance(tasks_data, list) else [])
                        for t in task_list:
                            if t.get("id") == task_id:
                                t["status"] = new_status
                                if new_status == "complete":
                                    t["completed_at"] = datetime.now(timezone.utc).isoformat()
                                break
                        if isinstance(tasks_data, dict):
                            tasks_data["tasks"] = task_list
                            tasks_file.write_text(json.dumps(tasks_data, indent=2))
                        else:
                            tasks_file.write_text(json.dumps(task_list, indent=2))
                        reply({"ok": True, "task_id": task_id, "status": new_status})
                    except Exception as e:
                        reply({"ok": False, "error": str(e)}, 500)

            # ── HITL approve ──
            elif path.startswith("/api/hitl/") and path.endswith("/approve"):
                task_id = path.split("/")[3]
                note    = body.get("note", "Approved via dashboard")
                try:
                    tasks_file = workspace / "TASKS.json"
                    tasks_data = json.loads(tasks_file.read_text())
                    task_list  = tasks_data.get("tasks", [])
                    for t in task_list:
                        if t.get("id") == task_id:
                            t["status"] = "in-progress"
                            t["hitl_resolved_at"] = datetime.now(timezone.utc).isoformat()
                            t["hitl_resolution"]  = f"APPROVED: {note}"
                            break
                    tasks_data["tasks"] = task_list
                    tasks_file.write_text(json.dumps(tasks_data, indent=2))
                    reply({"ok": True, "task_id": task_id, "action": "approved"})
                except Exception as e:
                    reply({"ok": False, "error": str(e)}, 500)

            # ── HITL reject ──
            elif path.startswith("/api/hitl/") and path.endswith("/reject"):
                task_id = path.split("/")[3]
                note    = body.get("note", "Rejected via dashboard")
                try:
                    tasks_file = workspace / "TASKS.json"
                    tasks_data = json.loads(tasks_file.read_text())
                    task_list  = tasks_data.get("tasks", [])
                    for t in task_list:
                        if t.get("id") == task_id:
                            t["status"] = "blocked"
                            t["hitl_resolved_at"] = datetime.now(timezone.utc).isoformat()
                            t["hitl_resolution"]  = f"REJECTED: {note}"
                            break
                    tasks_data["tasks"] = task_list
                    tasks_file.write_text(json.dumps(tasks_data, indent=2))
                    reply({"ok": True, "task_id": task_id, "action": "rejected"})
                except Exception as e:
                    reply({"ok": False, "error": str(e)}, 500)

            else:
                reply({"error": "not found"}, 404)

        def do_GET(self):
            path = self.path.split("?")[0]
            if path == "/" or path == "/index.html":
                self._serve_html()
            elif path == "/api/data":
                self._serve_json(workspace)
            elif path == "/api/stream":
                self._serve_sse()
            elif path.startswith("/assets/"):
                self._serve_asset(path)
            else:
                self.send_response(404)
                self.end_headers()
                self.wfile.write(b"Not found")

        # ── static HTML (React build preferred, legacy fallback) ──
        def _serve_html(self):
            react_build = SKILL_DIR / "dashboard-react/dist/index.html"
            html_path   = react_build if react_build.exists() else SKILL_DIR / "dashboard.html"
            try:
                content = html_path.read_text(encoding="utf-8")

                # Fetch initial data payload and inject into HTML
                data_snapshot = get_dashboard_data(workspace)
                payload_json = json.dumps(data_snapshot, default=str)
                injection = f'<script>window.INITIAL_DATA = {payload_json};</script>'

                # Insert right before </head>
                if "</head>" in content:
                    content = content.replace("</head>", f"{injection}\n</head>")

                content_bytes = content.encode("utf-8")

                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_cors()
                self.send_header("Cache-Control", "no-cache")
                self.send_header("Content-Length", str(len(content_bytes)))
                self.end_headers()
                self.wfile.write(content_bytes)
            except FileNotFoundError:
                self.send_response(404)
                self.end_headers()
                self.wfile.write(b"dashboard not found")

        # ── static assets (React build chunks) ──
        def _serve_asset(self, path: str):
            asset_path = SKILL_DIR / "dashboard-react/dist" / path.lstrip("/")
            if not asset_path.exists():
                self.send_response(404)
                self.end_headers()
                return
            ext = asset_path.suffix.lower()
            ct  = {
                ".js":   "application/javascript",
                ".css":  "text/css",
                ".png":  "image/png",
                ".svg":  "image/svg+xml",
                ".ico":  "image/x-icon",
                ".woff2":"font/woff2",
            }.get(ext, "application/octet-stream")
            content = asset_path.read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", ct)
            self.send_header("Cache-Control", "public, max-age=31536000, immutable")
            self.send_header("Content-Length", str(len(content)))
            self.end_headers()
            self.wfile.write(content)

        # ── REST snapshot ──
        def _serve_json(self, ws: Path):
            try:
                data = get_dashboard_data(ws)
                body = json.dumps(data, default=str).encode("utf-8")
                self.send_response(200)
                self.send_header("Content-Type", "application/json")
                self.send_cors()
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)
            except Exception as e:
                err = json.dumps({"error": str(e)}).encode("utf-8")
                self.send_response(500)
                self.send_header("Content-Type", "application/json")
                self.send_cors()
                self.end_headers()
                self.wfile.write(err)

        # ── SSE stream ──
        def _serve_sse(self):
            self.send_response(200)
            self.send_header("Content-Type",  "text/event-stream")
            self.send_header("Cache-Control", "no-cache")
            self.send_header("Connection",    "keep-alive")
            self.send_header("X-Accel-Buffering", "no")  # nginx compat
            self.send_cors()
            self.end_headers()

            # Subscribe to broadcaster
            cid, q = broadcaster.subscribe()

            def _write(text: str) -> bool:
                """Returns False if client disconnected."""
                try:
                    self.wfile.write(text.encode("utf-8"))
                    self.wfile.flush()
                    return True
                except (BrokenPipeError, ConnectionResetError, OSError):
                    return False

            try:
                # ── send initial snapshot immediately ──
                data    = get_dashboard_data(workspace)
                payload = json.dumps(data, default=str)
                if not _write(f"data: {payload}\n\n"):
                    return

                last_fallback = time.monotonic()
                last_keepalive = time.monotonic()

                while True:
                    now = time.monotonic()

                    # ── forced full refresh every FALLBACK_SECONDS ──
                    if now - last_fallback >= FALLBACK_SECONDS:
                        data    = get_dashboard_data(workspace)
                        payload = json.dumps(data, default=str)
                        if not _write(f"data: {payload}\n\n"):
                            return
                        last_fallback  = now
                        last_keepalive = now
                        continue

                    # ── keepalive comment every KEEPALIVE_SECONDS ──
                    if now - last_keepalive >= KEEPALIVE_SECONDS:
                        if not _write(": keepalive\n\n"):
                            return
                        last_keepalive = now

                    # ── drain the queue (file-change events) ──
                    try:
                        # Block up to 1s so we don't busy-spin
                        msg = q.get(timeout=1.0)
                        if not _write(f"data: {msg}\n\n"):
                            return
                        last_fallback  = time.monotonic()
                        last_keepalive = time.monotonic()
                        # Drain any additional queued events (coalesced)
                        while True:
                            try:
                                q.get_nowait()  # discard duplicates — next push is fresh
                            except queue.Empty:
                                break
                    except queue.Empty:
                        pass  # timeout — loop back to check keepalive / fallback

            finally:
                broadcaster.unsubscribe(cid)

    return DashboardHandler


# ═══════════════════════════════════════════════════════════════════════════════
#  ENTRY POINT
# ═══════════════════════════════════════════════════════════════════════════════

def main():
    parser = argparse.ArgumentParser(description="CooperCorp AGI Dashboard (file-watcher edition)")
    parser.add_argument("--port",      type=int, default=8080)
    parser.add_argument("--workspace", type=str,
                        default=str(Path.home() / ".openclaw" / "workspace"))
    parser.add_argument("--no-browser", action="store_true")
    args = parser.parse_args()

    workspace = Path(os.path.expanduser(args.workspace))
    if not workspace.exists():
        print(f"⚠  Workspace not found: {workspace}", file=sys.stderr)

    # ── shared broadcaster ──
    broadcaster = Broadcaster()

    # ── workspace watcher → broadcast on change ──
    def _on_change():
        # Force a refresh of the slow cache in the background so
        # agent statuses are instantly up-to-date on files change.
        threading.Thread(target=_slow_cache._refresh, daemon=True).start()

        if broadcaster.client_count == 0:
            return  # no clients — skip the work
        try:
            data    = get_dashboard_data(workspace)
            payload = json.dumps(data, default=str)
            broadcaster.push(payload)
        except Exception as e:
            broadcaster.push(json.dumps({"error": str(e)}))

    watcher = WorkspaceWatcher(workspace, _on_change)
    watcher.start()

    # ── HTTP server ──
    handler = make_handler(workspace, broadcaster)
    server  = ThreadingHTTPServer(("", args.port), handler)

    url = f"http://localhost:{args.port}"
    print(f"\n🚀 CooperCorp AGI Dashboard — File-Watcher Edition")
    print(f"   URL:       {url}")
    print(f"   Workspace: {workspace}")
    print(f"   SSE:       {url}/api/stream  (instant on file change, {FALLBACK_SECONDS}s fallback)")
    print(f"   Debounce:  {int(DEBOUNCE_SECONDS * 1000)}ms")
    print(f"   Press Ctrl+C to stop\n")

    if not args.no_browser:
        def _open():
            time.sleep(0.9)
            webbrowser.open(url)
        threading.Thread(target=_open, daemon=True).start()

    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\n👋  Dashboard stopped.")
        watcher.stop()
        server.shutdown()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
auto-dispatch.py — AGI-Farm Auto-Dispatcher
Part of the AGI-Farm skill (github.com/oabdelmaksoud/AGI-Farm).

Usage:
  python3 auto-dispatch.py [--workspace PATH] [--orchestrator ID] [--execute]

  --workspace PATH    Team workspace directory (default: ~/.openclaw/workspace)
  --orchestrator ID   Orchestrator agent id to skip (default: main)
  --execute           Actually trigger agents (default: dry-run preview only)

Cron (every 1 min, full-auto):
  * * * * * python3 ~/.openclaw/skills/agi-farm/auto-dispatch.py \\
              --workspace ~/.openclaw/workspace --execute \\
              >> ~/.openclaw/workspace/logs/auto-dispatch.log 2>&1

Two jobs per run:
  1. HITL notifications — detect needs_human_decision tasks, push alert to user
  2. Agent dispatch     — fire openclaw agent sessions for pending tasks

Safety rails:
  - Orchestrator never auto-triggered (needs human in loop)
  - 30-min cooldown per agent (no re-trigger spam)
  - All eligible agents run in parallel
  - Blocked agents skipped ([BLOCKED] in outbox)
  - Dependency checking: task only triggers when all depends_on are complete
  - Rate-limit detection + 10-min backoff
  - Stale in-progress auto-reset (>90 min, no outbox activity)
  - HITL re-notify cooldown: 2h per task
  - Full audit log → DISPATCHER_STATE.json
"""

import json
import os
import shutil
import subprocess
import sys
import time
import tempfile
from pathlib import Path
from datetime import datetime, timezone, timedelta

# ── openclaw binary resolution ────────────────────────────────────────────────
def _find_openclaw() -> str:
    """Locate the openclaw binary robustly for cron/LaunchAgent environments.

    Search order:
      1. $OPENCLAW_BIN env var (explicit override)
      2. shutil.which() — honours $PATH if available
      3. Common install locations on macOS/Linux
    """
    if os.environ.get("OPENCLAW_BIN"):
        return os.environ["OPENCLAW_BIN"]
    found = shutil.which("openclaw")
    if found:
        return found
    for candidate in (
        "/opt/homebrew/bin/openclaw",   # macOS Apple-silicon Homebrew
        "/usr/local/bin/openclaw",      # macOS Intel Homebrew / Linux
        "/usr/bin/openclaw",            # system-wide Linux installs
        str(Path.home() / ".local/bin/openclaw"),  # user-local pip installs
    ):
        if Path(candidate).is_file():
            return candidate
    return "openclaw"  # last resort — let subprocess raise a clear FileNotFoundError

OPENCLAW_BIN = _find_openclaw()

# ── Constants ─────────────────────────────────────────────────────────────────
COOLDOWN_MINUTES         = 30
HITL_NOTIFY_COOLDOWN_H   = 2
RATE_LIMIT_BACKOFF_MIN   = 10
STALE_INPROGRESS_MINUTES = 90

RATE_LIMIT_SIGNALS = [
    "rate limit", "rate_limit", "429", "too many requests",
    "⚠️ api rate limit", "please try again later",
]

# ── Args (resolved before anything else) ─────────────────────────────────────
def parse_args():
    args = sys.argv[1:]
    workspace    = Path.home() / ".openclaw" / "workspace"
    orchestrator = "main"
    execute      = False

    i = 0
    while i < len(args):
        if args[i] == "--workspace" and i + 1 < len(args):
            workspace = Path(args[i + 1]).expanduser(); i += 2
        elif args[i] == "--orchestrator" and i + 1 < len(args):
            orchestrator = args[i + 1]; i += 2
        elif args[i] == "--execute":
            execute = True; i += 1
        else:
            i += 1

    return workspace, orchestrator, execute

# ── Helpers ───────────────────────────────────────────────────────────────────
def read_json(path):
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception:
        return {}

def write_json(path, data):
    Path(path).write_text(json.dumps(data, indent=2, default=str), encoding="utf-8")

def has_inbox_messages(inboxes_dir: Path, agent_id: str) -> bool:
    inbox = inboxes_dir / f"{agent_id}.md"
    if not inbox.exists():
        return False
    content = inbox.read_text(encoding="utf-8")
    return "TASK_ID:" in content or (
        any(l.startswith("## ") for l in content.splitlines())
        and "_No messages_" not in content
        and "No messages" not in content
    )

def is_blocked(outboxes_dir: Path, agent_id: str) -> bool:
    outbox = outboxes_dir / f"{agent_id}.md"
    if not outbox.exists():
        return False
    return "[BLOCKED]" in outbox.read_text(encoding="utf-8")

def is_rate_limited(agent_id: str, state: dict, now: datetime) -> bool:
    rl = state.get("rate_limited_until", {}).get(agent_id)
    if not rl:
        return False
    try:
        return now < datetime.fromisoformat(rl)
    except Exception:
        return False

def deps_satisfied(task: dict, task_index: dict) -> tuple[bool, list]:
    blocking = [
        dep for dep in task.get("depends_on", [])
        if task_index.get(dep, {}).get("status") != "complete"
    ]
    return len(blocking) == 0, blocking

def detect_rate_limit(text: str) -> bool:
    low = text.lower()
    return any(sig in low for sig in RATE_LIMIT_SIGNALS)

def trigger_agent(agent_id: str, task_title: str) -> tuple[bool, str, bool]:
    msg = (
        f"You have pending work in your inbox. "
        f"Please read comms/inboxes/{agent_id}.md and begin work on your "
        f"highest-priority pending task now. Task: {task_title}"
    )
    try:
        tmp = tempfile.NamedTemporaryFile(
            mode="w", suffix=".log", delete=False, prefix=f"dispatch_{agent_id}_"
        )
        tmp.close()
        tmp_path = Path(tmp.name)
        proc = subprocess.Popen(
            [OPENCLAW_BIN, "agent", "--agent", agent_id, "--message", msg],
            stdout=open(tmp_path, "w"), stderr=subprocess.STDOUT,
            start_new_session=True,
        )
        try:
            early_exit = proc.wait(timeout=15)
        except subprocess.TimeoutExpired:
            early_exit = None

        try:
            output = tmp_path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            output = ""
        try:
            tmp_path.unlink()
        except Exception:
            pass
        if detect_rate_limit(output):
            proc.terminate()
            return False, "rate_limit", True
        if early_exit is not None and early_exit != 0:
            return False, f"exited rc={early_exit}: {output.strip()[:200]}", False
        return True, f"pid={proc.pid}", False
    except Exception as e:
        return False, str(e), False

def send_hitl_notification(orchestrator: str, hitl_tasks: list) -> tuple[bool, str]:
    lines = [f"• {t['id']}: {t['title']}" for t in hitl_tasks]
    msg = (
        f"🚨 HITL Required — {len(hitl_tasks)} task(s) need your decision:\n\n"
        + "\n".join(lines)
        + "\n\nPlease reply so I can unblock the team. "
        "(Dashboard Tasks tab → 🚨 HITL filter for full context.)"
    )
    try:
        proc = subprocess.Popen(
            [OPENCLAW_BIN, "agent", "--agent", orchestrator, "--message", msg, "--deliver"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            start_new_session=True,
        )
        time.sleep(1)
        return True, f"pid={proc.pid}"
    except Exception as e:
        return False, str(e)

# ── Job 0: Stale In-Progress Reset ───────────────────────────────────────────
def reset_stale_tasks(tasks: list, tasks_file: Path, outboxes_dir: Path, now: datetime):
    reset_ids = []
    for t in tasks:
        if t.get("status") != "in-progress":
            continue
        agent_id = t.get("assigned_to", "")
        started  = t.get("started_at") or t.get("decision_at")
        if not started:
            continue
        try:
            age_min = (now - datetime.fromisoformat(
                started.replace("Z", "+00:00"))).total_seconds() / 60
        except Exception:
            continue
        if age_min < STALE_INPROGRESS_MINUTES:
            continue
        outbox = outboxes_dir / f"{agent_id}.md"
        if outbox.exists():
            mtime = datetime.fromtimestamp(outbox.stat().st_mtime, tz=timezone.utc)
            if mtime > datetime.fromisoformat(started.replace("Z", "+00:00")):
                continue
        t["status"] = "pending"
        t["note"]   = f"Auto-reset: in-progress >{STALE_INPROGRESS_MINUTES}m with no outbox activity"
        t.pop("started_at", None)
        reset_ids.append(t["id"])
        print(f"[stale-reset] ⟳ {t['id']} ({agent_id}) — reset to pending")

    if reset_ids:
        try:
            raw = read_json(tasks_file)
            if isinstance(raw, dict):
                raw["tasks"] = tasks
                raw.setdefault("meta", {})["last_updated"] = now.isoformat()
                write_json(tasks_file, raw)
        except Exception as e:
            print(f"[stale-reset] ❌ persist failed: {e}")
    return tasks, reset_ids

# ── Job 1: HITL Notifications ─────────────────────────────────────────────────
def run_hitl_notifications(tasks: list, state: dict, now: datetime, orchestrator: str) -> dict:
    hitl_tasks  = [t for t in tasks if t.get("status") == "needs_human_decision"]
    notified_at = state.get("hitl_notified_at", {})
    to_notify   = []

    for t in hitl_tasks:
        tid  = t.get("id", "")
        last = notified_at.get(tid)
        if last:
            try:
                elapsed_h = (now - datetime.fromisoformat(last)).total_seconds() / 3600
                if elapsed_h < HITL_NOTIFY_COOLDOWN_H:
                    print(f"[hitl] ⏭  {tid} cooldown ({elapsed_h:.1f}h/{HITL_NOTIFY_COOLDOWN_H}h)")
                    continue
            except Exception:
                pass
        to_notify.append(t)

    if not to_notify:
        print(f"[hitl] ok ({len(hitl_tasks)} HITL tasks, all within cooldown)")
        return notified_at

    print(f"[hitl] 🚨 notifying for {[t['id'] for t in to_notify]}")
    ok, info = send_hitl_notification(orchestrator, to_notify)
    if ok:
        for t in to_notify:
            notified_at[t["id"]] = now.isoformat()
        print(f"[hitl] ✅ sent ({info})")
    else:
        print(f"[hitl] ❌ failed: {info}")
    return notified_at

# ── Job 2a: Dry-Run Preview ───────────────────────────────────────────────────
def dry_run_dispatch(tasks: list, state: dict, now: datetime,
                     skip_agents: set, inboxes_dir: Path, outboxes_dir: Path):
    pending    = [t for t in tasks if isinstance(t, dict) and t.get("status") == "pending"]
    last_trig  = state.get("last_triggered", {})
    task_index = {t["id"]: t for t in tasks if isinstance(t, dict)}
    would_trigger, would_skip = [], []

    seen: dict = {}
    for task in pending:
        aid = task.get("assigned_to")
        if aid and aid not in seen:
            seen[aid] = task

    for aid, task in seen.items():
        title = task.get("title", "")
        if aid in skip_agents:
            would_skip.append({"agent": aid, "reason": "orchestrator"})
        elif is_rate_limited(aid, state, now):
            would_skip.append({"agent": aid, "reason": "rate_limited"})
        elif (lt := last_trig.get(aid)) and \
             (now - datetime.fromisoformat(lt)).total_seconds() < COOLDOWN_MINUTES * 60:
            remaining = int((COOLDOWN_MINUTES * 60 - (now - datetime.fromisoformat(lt)).total_seconds()) / 60)
            would_skip.append({"agent": aid, "reason": f"cooldown ({remaining}m)"})
        elif not (sat := deps_satisfied(task, task_index))[0]:
            would_skip.append({"agent": aid, "reason": f"waiting for {sat[1]}"})
        elif is_blocked(outboxes_dir, aid):
            would_skip.append({"agent": aid, "reason": "BLOCKED"})
        elif not has_inbox_messages(inboxes_dir, aid):
            would_skip.append({"agent": aid, "reason": "empty inbox"})
        else:
            would_trigger.append({"agent": aid, "task_id": task.get("id"), "title": title})
            print(f"[dry-run] → would trigger {aid}: {task.get('id')} — {title[:55]}")

    for s in would_skip:
        print(f"[dry-run] → would skip   {s['agent']}: {s['reason']}")

    return would_trigger, would_skip

# ── Job 2b: Live Dispatch ─────────────────────────────────────────────────────
def run_dispatch(tasks: list, state: dict, now: datetime,
                 skip_agents: set, inboxes_dir: Path, outboxes_dir: Path):
    pending    = [t for t in tasks if isinstance(t, dict) and t.get("status") == "pending"]
    last_trig  = state.get("last_triggered", {})
    rate_lim   = state.get("rate_limited_until", {})
    task_index = {t["id"]: t for t in tasks if isinstance(t, dict)}
    triggered, skipped = [], []

    seen: dict = {}
    for task in pending:
        aid = task.get("assigned_to")
        if aid and aid not in seen:
            seen[aid] = task

    for aid, task in seen.items():
        if aid in skip_agents:
            skipped.append({"agent": aid, "reason": "orchestrator"})
            continue
        if is_rate_limited(aid, state, now):
            skipped.append({"agent": aid, "reason": f"rate_limited until {rate_lim.get(aid)}"})
            print(f"[dispatch] ⏸  {aid} rate-limited")
            continue
        if (lt := last_trig.get(aid)):
            elapsed = (now - datetime.fromisoformat(lt)).total_seconds()
            if elapsed < COOLDOWN_MINUTES * 60:
                remaining = int((COOLDOWN_MINUTES * 60 - elapsed) / 60)
                skipped.append({"agent": aid, "reason": f"cooldown ({remaining}m)"})
                continue
        satisfied, blocking = deps_satisfied(task, task_index)
        if not satisfied:
            skipped.append({"agent": aid, "reason": f"waiting for {blocking}"})
            print(f"[dispatch] ⏳ {aid}/{task['id']} blocked by {blocking}")
            continue
        if is_blocked(outboxes_dir, aid):
            skipped.append({"agent": aid, "reason": "BLOCKED"})
            continue
        if not has_inbox_messages(inboxes_dir, aid):
            skipped.append({"agent": aid, "reason": "empty inbox"})
            continue

        title = task.get("title", task.get("id", "pending task"))
        ok, info, rl_hit = trigger_agent(aid, title)

        if rl_hit:
            until = (now + timedelta(minutes=RATE_LIMIT_BACKOFF_MIN)).isoformat()
            rate_lim[aid] = until
            skipped.append({"agent": aid, "reason": f"rate_limit → backoff until {until}"})
            print(f"[dispatch] ⚠️  {aid} hit rate limit — backing off {RATE_LIMIT_BACKOFF_MIN}m")
        elif ok:
            last_trig[aid] = now.isoformat()
            triggered.append({"agent": aid, "task_id": task.get("id"), "title": title, "at": now.isoformat()})
            print(f"[dispatch] ✅ triggered {aid} → {title[:60]}")
        else:
            skipped.append({"agent": aid, "reason": f"failed: {info}"})
            print(f"[dispatch] ❌ failed   {aid} → {info[:80]}")

    return triggered, skipped, last_trig, rate_lim

# ── Main ──────────────────────────────────────────────────────────────────────
def main():
    workspace, orchestrator, execute = parse_args()

    tasks_file   = workspace / "TASKS.json"
    state_file   = workspace / "DISPATCHER_STATE.json"
    inboxes_dir  = workspace / "comms" / "inboxes"
    outboxes_dir = workspace / "comms" / "outboxes"
    skip_agents  = {orchestrator}

    if not execute:
        print(f"[auto-dispatch] DRY-RUN — workspace={workspace} orchestrator={orchestrator}")
        print("[auto-dispatch] Pass --execute to trigger agents\n")

    now   = datetime.now(timezone.utc)
    state = read_json(state_file) or {}

    tasks_data = read_json(tasks_file)
    tasks = tasks_data.get("tasks", []) if isinstance(tasks_data, dict) else (tasks_data or [])

    # ── Job 0: Stale reset ────────────────────────────────────────────────────
    tasks, reset_ids = reset_stale_tasks(tasks, tasks_file, outboxes_dir, now)
    if reset_ids:
        print(f"[stale-reset] reset: {reset_ids}")

    # ── Job 1: HITL notifications ─────────────────────────────────────────────
    if execute:
        notified_at = run_hitl_notifications(tasks, state, now, orchestrator)
    else:
        notified_at = state.get("hitl_notified_at", {})

    # ── Job 2: Dispatch ───────────────────────────────────────────────────────
    if not execute:
        would_trigger, would_skip = dry_run_dispatch(
            tasks, state, now, skip_agents, inboxes_dir, outboxes_dir)
        print(f"\n[dry-run] Would trigger: {[t['agent'] for t in would_trigger]}")
        print(f"[dry-run] Would skip:    {[s['agent']+' ('+s['reason']+')' for s in would_skip]}")
        print(f"\nRun with --execute to apply.")
        return

    triggered, skipped, last_trig, rate_lim = run_dispatch(
        tasks, state, now, skip_agents, inboxes_dir, outboxes_dir)

    # ── Persist state ─────────────────────────────────────────────────────────
    history = state.get("history", [])
    run_summary = {
        "run_at":        now.isoformat(),
        "workspace":     str(workspace),
        "pending_count": sum(1 for t in tasks if t.get("status") == "pending"),
        "hitl_count":    sum(1 for t in tasks if t.get("status") == "needs_human_decision"),
        "triggered":     triggered,
        "skipped":       skipped,
    }
    history.append(run_summary)
    if len(history) > 200:
        history = history[-200:]

    write_json(state_file, {
        "last_run":           now.isoformat(),
        "last_triggered":     last_trig,
        "rate_limited_until": rate_lim,
        "hitl_notified_at":   notified_at,
        "last_summary":       run_summary,
        "history":            history,
    })

    print(
        f"[auto-dispatch] {now.strftime('%H:%M UTC')} workspace={workspace.name} — "
        f"{run_summary['pending_count']} pending · {run_summary['hitl_count']} HITL · "
        f"triggered {len(triggered)} · skipped {len(skipped)}"
    )
    for s in skipped:
        print(f"  ↳ skip {s['agent']}: {s['reason']}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
register-crons.py — Register cron jobs for an agi-farm team.

Reads team.json, detects timezone from OpenClaw config, registers the
orchestrator heartbeat + standup + specialist crons for every agent in
the roster. Skips any cron that already exists by name.

Usage:
    python3 register-crons.py [--team-json PATH] [--dry-run]
"""

import argparse
import json
import subprocess
from pathlib import Path
from datetime import datetime, timezone


def read_json(path):
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception:
        return {}


def get_timezone() -> str:
    """Read timezone from openclaw.json, fall back to UTC."""
    cfg_path = Path.home() / ".openclaw/openclaw.json"
    try:
        cfg = json.loads(cfg_path.read_text())
        tz = cfg.get("session", {}).get("timezone") or \
             cfg.get("timezone") or \
             cfg.get("settings", {}).get("timezone")
        if tz:
            return tz
    except Exception:
        pass
    # Try system timezone
    try:
        tz = subprocess.run(
            ["openssl", "rand", "-hex", "1"],  # dummy
            capture_output=True
        )
        import time
        return datetime.now(timezone.utc).astimezone().tzname() or "UTC"
    except Exception:
        pass
    return "UTC"


def existing_cron_names() -> set:
    try:
        r = subprocess.run(
            ["openclaw", "cron", "list"],
            capture_output=True, text=True, timeout=8
        )
        names = set()
        for line in r.stdout.splitlines()[1:]:
            parts = line.split()
            if len(parts) >= 2:
                names.add(parts[1])
        return names
    except Exception:
        return set()


def cron_add(args: list, dry_run: bool) -> bool:
    cmd = ["openclaw", "cron", "add"] + args
    if dry_run:
        print(f"  [dry-run] {' '.join(cmd)}")
        return True
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=15)
        return r.returncode == 0
    except Exception:
        return False


def register_all(team: dict, tz: str, dry_run: bool):
    agent_ids  = {a["id"] for a in team["agents"]}
    team_lower = team["team_name"].lower().replace(" ", "-")
    existing   = existing_cron_names()

    # ── Core orchestrator jobs ──────────────────────────────────────────────
    CORE_JOBS = [
        {
            "name":    f"{team_lower}-heartbeat",
            "agent":   "main",
            "cron":    "*/30 * * * *",
            "message": "Heartbeat: verify all agents available, flag stuck tasks, update HEARTBEAT.md.",
            "timeout": "60",
            "flags":   ["--no-deliver"],
        },
        {
            "name":    f"{team_lower}-morning-standup",
            "agent":   "main",
            "cron":    "0 8 * * *",
            "message": "Morning standup: read TASKS.json, check agent status, plan the day. Report key items.",
            "timeout": "120",
            "flags":   [],
        },
    ]

    # ── Specialist jobs — only if agent in roster ───────────────────────────
    SPECIALIST_JOBS = {
        "vigil": {
            "name":    f"{team_lower}-vigil-heartbeat",
            "cron":    "*/30 * * * *",
            "message": "Heartbeat: check AGENT_STATUS.json for stuck agents, TASKS.json for overdue tasks, broadcast.md for alerts. Update DASHBOARD.md. Pull next IMPROVEMENT_BACKLOG item if queue empty.",
            "timeout": "90",
            "flags":   ["--no-deliver"],
        },
        "cipher": {
            "name":    f"{team_lower}-cipher-synthesis",
            "cron":    "0 */6 * * *",
            "message": "Knowledge synthesis: read agent outboxes, extract learnings, update MEMORY.md (≤200 lines), update SHARED_KNOWLEDGE.json, update FAILURES.md if needed.",
            "timeout": "120",
            "flags":   [],
        },
        "nova": {
            "name":    f"{team_lower}-nova-digest",
            "cron":    "0 9 * * 1",
            "message": "Weekly R&D digest: summarize active experiments, publish findings to broadcast.md, update EXPERIMENTS.json.",
            "timeout": "120",
            "flags":   [],
        },
        "evolve": {
            "name":    f"{team_lower}-evolve-scan",
            "cron":    "0 2 * * *",
            "message": "Daily process scan: review TASKS.json failure patterns, update IMPROVEMENT_BACKLOG.json, propose process improvements if same failure occurred 3+ times.",
            "timeout": "120",
            "flags":   ["--no-deliver"],
        },
    }

    results = {"registered": [], "skipped": [], "failed": []}

    for job in CORE_JOBS:
        if job["name"] in existing:
            print(f"  ⏭  skip (exists): {job['name']}")
            results["skipped"].append(job["name"])
            continue
        args = [
            "--name",            job["name"],
            "--agent",           job["agent"],
            "--cron",            job["cron"],
            "--tz",              tz,
            "--session",         "isolated",
            "--message",         job["message"],
            "--timeout-seconds", job["timeout"],
        ] + job.get("flags", [])
        ok = cron_add(args, dry_run)
        if ok:
            print(f"  ✅ registered: {job['name']}")
            results["registered"].append(job["name"])
        else:
            print(f"  ❌ failed:     {job['name']}")
            results["failed"].append(job["name"])

    for aid, job in SPECIALIST_JOBS.items():
        if aid not in agent_ids:
            continue
        if job["name"] in existing:
            print(f"  ⏭  skip (exists): {job['name']}")
            results["skipped"].append(job["name"])
            continue
        args = [
            "--name",            job["name"],
            "--agent",           aid,
            "--cron",            job["cron"],
            "--tz",              tz,
            "--session",         "isolated",
            "--message",         job["message"],
            "--timeout-seconds", job["timeout"],
        ] + job.get("flags", [])
        ok = cron_add(args, dry_run)
        if ok:
            print(f"  ✅ registered: {job['name']} ({aid})")
            results["registered"].append(job["name"])
        else:
            print(f"  ❌ failed:     {job['name']} ({aid})")
            results["failed"].append(job["name"])

    print(f"\n  Summary: {len(results['registered'])} registered, "
          f"{len(results['skipped'])} skipped, {len(results['failed'])} failed")
    return results


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--team-json", default=str(
        Path.home() / ".openclaw/workspace/agi-farm-bundle/team.json"))
    p.add_argument("--dry-run", action="store_true")
    args = p.parse_args()

    team = read_json(args.team_json)
    if not team:
        print(f"❌ team.json not found: {args.team_json}")
        return

    tz = get_timezone()
    print(f"🕐 Timezone: {tz}")
    print(f"👥 Team: {team['team_name']} ({len(team['agents'])} agents)")
    print(f"{'[DRY-RUN] ' if args.dry_run else ''}Registering crons...\n")

    register_all(team, tz, args.dry_run)


if __name__ == "__main__":
    main()
